import {freshState,addMoney,addXP,advance,registerOffline} from '../core/game.js';import {JOBS,ITEMS,SKILLS} from '../data/config.js';
export function attach(api){const panel=document.createElement('details');panel.className='debug-panel';panel.innerHTML='<summary>Development tools</summary>';const actions={'Add Money':()=>addMoney(api.get(),100000),'Add Gems':()=>api.get().gems+=100,'Add XP':()=>addXP(api.get(),1000),'Level Up':()=>addXP(api.get(),Math.round(100*Math.pow(api.get().level,1.2))),'Unlock All':()=>{const s=api.get();addXP(s,1e7);s.jobs=JOBS.map(j=>j.id);s.items=ITEMS.map(i=>i.id);for(const k of SKILLS)s.skills[k]=20;},'Simulate Offline Time':()=>{const s=api.get();s.lastTick-=3600000;registerOffline(s,advance(s,Date.now(),true));},'QA: starter eligibility':()=>{const s=api.get();s.playtime=Math.max(600,s.playtime);s.level=Math.max(5,s.level);s.tutorial=3;s.stats.work=Math.max(10,s.stats.work);s.stats.bought=Math.max(2,s.stats.bought);s.achievements=[...new Set([...s.achievements,'firstMoney','firstJob','firstItem'])];},'QA: measure 5 seconds':()=>measure(api,panel),'QA: 360px width':()=>{document.querySelector('.app-shell').classList.toggle('preview-viewport');},'QA: reward effects':()=>{api.motion.celebrate('Level Up','Animation test','spark');api.motion.coins();api.motion.xp();api.motion.shake();}};
for(const [label,fn] of Object.entries(actions)){const b=document.createElement('button');b.textContent=label;b.addEventListener('click',()=>{fn();api.refresh();});panel.append(b);}document.body.append(panel);}
function measure(api,panel){let last=performance.now(),start=last,deltas=[],longTasks=0;const out=panel.querySelector('.diagnostic-panel')||panel.appendChild(Object.assign(document.createElement('div'),{className:'diagnostic-panel'}));out.textContent='Measuring…';let observer;try{observer=new PerformanceObserver(list=>longTasks+=list.getEntries().length);observer.observe({type:'longtask',buffered:false});}catch{}const frame=now=>{deltas.push(now-last);last=now;if(now-start<5000){requestAnimationFrame(frame);return;}observer?.disconnect();const sorted=deltas.slice(1).sort((a,b)=>a-b),mean=sorted.reduce((a,b)=>a+b,0)/sorted.length;out.textContent=`Frames: ${sorted.length}\nAvg frame: ${mean.toFixed(1)}ms\nP95: ${sorted[Math.floor(sorted.length*.95)]?.toFixed(1)}ms\nLong tasks: ${longTasks}\nActive particles: ${api.motion.particles}\nUI animations: ${api.motion.active.size}`;};requestAnimationFrame(frame);}
